<?php
// Explicit, reviewed actions. All stock writes reuse the existing order posting workflow.
function oi_assets(){static $sent=false;if($sent)return;$sent=true;echo '<link rel="stylesheet" href="assets/order_interactions.css?v=5.9.22"><script src="assets/order_interactions.js?v=5.9.24" defer></script>';}
function oi_buttons($id){$ref=om_allowed()?'<button type="button" class="btn ghost sm" data-oi="references" data-order="'.(int)$id.'">'.(or_booking(om_order($id))?'Link Order ID':'Tracking Numbers').'</button> ':'';$statusLabel=sp_terminal_delivery(om_order($id))?'Report Return / Refund':'Update Status';return $ref.(om_allowed()?'<button type="button" class="btn secondary sm" data-oi="manual" data-order="'.(int)$id.'">'.e($statusLabel).'</button> ':'').'<button type="button" class="btn ghost sm" data-oi="history" data-order="'.(int)$id.'">Update History</button>';}
function oi_form($action,$extra=[]){echo '<form data-oi-form><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="action" value="'.e($action).'">';foreach($extra as $k=>$v)echo '<input type="hidden" name="'.e($k).'" value="'.e($v).'">';}
function oi_exclusion($b,$no){return $b['meta']['excluded_orders'][hash('sha256',(string)$no)]??null;}
function oi_exclude($id,$revision,$orders,$reason,$undo=false){om_require();$reason=process_reason($reason);if(!is_array($orders)||!$orders||count($orders)>5000)throw new Exception('Select 1 to 5000 orders.');foreach($orders as $no)if(!is_scalar($no))throw new Exception('Invalid order selection.');$orders=array_values(array_unique(array_map('strval',$orders)));return process_transaction(function()use($id,$revision,$orders,$reason,$undo){om_query('SELECT id FROM om_uploads WHERE id=? FOR UPDATE',[$id])->fetch();$b=om_upload($id);om_owner($b);if((int)$b['revision']!==(int)$revision)throw new Exception('Review changed. Reopen verification before removing orders.');if(!empty($b['meta']['manual']))throw new Exception('Manual updates cannot be removed as file rows.');$present=array_map('strval',array_column($b['rows'],'order'));foreach($orders as $no)if(!in_array($no,$present,true))throw new Exception('Selected order is not in this upload.');foreach($orders as $no){$key=hash('sha256',$no);if($undo)unset($b['meta']['excluded_orders'][$key]);else $b['meta']['excluded_orders'][$key]=['order'=>$no,'reason'=>$reason,'user_id'=>current_user()['id'],'at'=>date('Y-m-d H:i:s')];$o=om_find($b['platform'],$b['shop'],$no);om_event($o['id']??null,$id,$undo?'Order restored to upload':'Order removed from upload',['order'=>$no,'reason'=>$reason,'source'=>'Upload review','stock_changed'=>false]);}om_query('UPDATE om_uploads SET meta_json=?,revision=revision+1 WHERE id=?',[json_encode($b['meta']),$id]);audit($undo?'Restore upload orders':'Remove upload orders','Order Monitoring',(string)$id,json_encode(['orders'=>$orders,'reason'=>$reason,'stock_changed'=>false]));return count($orders);});}
function oi_manual_plan($id,$input,$snapshot=null){
 om_require();$o=om_order($id);stock_platform($o['platform']);$status=$input['status']??'';sp_assert_manual($o,$status);if(!in_array($status,['To Ship','Shipped','Delivered','Completed','Cancelled','Failed Delivery','Return / Refund'],true))throw new Exception('Choose a supported status.');$reason=process_reason($input['reason']??'');$event=process_date($input['event_date']??'');if($event>date('Y-m-d')||$event<substr($o['created_order_at'],0,10))throw new Exception('Actual event date must be between order creation and today.');
 $snapshot=$snapshot??date('Y-m-d H:i:s');$dispatch=null;if($o['posting']==='Not Posted'&&in_array($status,['Shipped','Delivered','Completed'],true)){$dispatch=process_date($status==='Shipped'?$event:($input['dispatch_date']??''));if($dispatch>$event||$dispatch>date('Y-m-d'))throw new Exception('Dispatch date cannot follow the event date.');}
 if($o['posting']==='Posted'&&in_array($status,['Shipped','Delivered','Completed'],true)){$last=om_query('SELECT MAX(f.txn_date) FROM om_postings p JOIN outflows f ON f.id=p.outflow_id WHERE p.order_id=?',[$id])->fetchColumn();if($last&&$event<$last)throw new Exception('Actual event cannot precede the posted dispatch date.');}
 // A confirmed cancellation may release held availability, never add physical stock.
 $cancel=$status==='Cancelled'&&$o['posting']==='Not Posted';if($cancel&&(empty($input['warehouse_ack'])||om_query('SELECT COUNT(*) FROM om_postings WHERE order_id=?',[$id])->fetchColumn()))throw new Exception('Confirm all units remain in the warehouse and no dispatch was posted.');
 $previous=om_query("SELECT details_json FROM om_events WHERE order_id=? AND event_type='Manual status updated' ORDER BY id DESC LIMIT 1",[$id])->fetchColumn();$previous=$previous?json_decode($previous,true):[];if(!empty($previous['actual_event_date'])&&$event<$previous['actual_event_date'])throw new Exception('Actual event predates the latest manual status event.');
 $lines=[];foreach(om_query('SELECT * FROM om_lines WHERE order_id=? ORDER BY id',[$id]) as $l){$r=json_decode($l['source_json'],true);$r['components']=json_decode($l['components_json'],true);$lines[]=$r;}
 if(!$lines){foreach(om_existing_totals($id) as $pid=>$qty){$p=stock_row($pid);$lines[]=['row'=>count($lines)+1,'order'=>$o['order_no'],'created'=>$o['created_order_at'],'key'=>hash('sha256','legacy|'.$id.'|'.$pid),'item'=>$p['name'],'name'=>$p['name'],'variation'=>'','external'=>'','sku'=>$p['master_sku'],'qty'=>$qty,'item_ids'=>[],'components'=>[['product_id'=>$pid,'per_bundle'=>1]]];}}
 if(!$lines)throw new Exception('No verified order items are available. Review the original registration.');foreach($lines as &$r){unset($r['source_date_rows'],$r['date_errors']);$r['status']=$status;$r['booking_only']=false;$r['raw_status']='Manual: '.$status;$r['aftersales']=in_array($status,['Failed Delivery','Return / Refund'],true);$r['ship_at']=$dispatch?min($dispatch.' 23:59:59',$snapshot):null;$r['ship_source']=$dispatch?'Verified manual dispatch date':'';$r['delivered_at']=in_array($status,['Delivered','Completed'],true)?$event.' 23:59:59':null;if($r['delivered_at']&&$r['delivered_at']>$snapshot)$r['delivered_at']=$snapshot;}unset($r);
 $meta=['platform'=>$o['platform'],'shop'=>$o['shop'],'fulfillment_date'=>$o['fulfillment_date'],'snapshot'=>$snapshot,'coverage_from'=>substr($o['created_order_at'],0,10),'coverage_to'=>substr($o['created_order_at'],0,10),'all_statuses'=>false,'manual'=>true,'reason'=>$reason,'actual_event_date'=>$event,'late'=>false];$b=['id'=>0,'revision'=>1,'kind'=>'Status','platform'=>$o['platform'],'shop'=>$o['shop'],'meta'=>$meta,'rows'=>$lines];$plan=om_plan($b);$row=$plan['orders'][0];if($row['errors'])throw new Exception(implode(' · ',$row['errors']));if($row['action']==='Unchanged'&&!oa_pending($o))throw new Exception('This status is already recorded. No update is needed.');
 $effects=[];foreach($row['totals'] as $pid=>$qty){$s=stock_row($pid);$reserved=om_reserved($pid);$held=(int)om_query('SELECT qty FROM om_reservations WHERE order_id=? AND product_id=?',[$id,$pid])->fetchColumn();$deduct=$row['action']==='Dispatch / post'?$qty:0;$release=$cancel?$held:$deduct;$effects[]=['sku'=>$s['master_sku'],'product'=>$s['name'],'physical_before'=>$s['physical'],'physical_after'=>$s['physical']-$deduct,'reserved_before'=>$reserved,'reserved_after'=>$reserved-$release,'available_before'=>$s['current']-$reserved,'available_after'=>$s['current']-$deduct-$reserved+$release];}
 $saved=['order_id'=>(int)$id,'order_revision'=>(int)$o['revision'],'input'=>['status'=>$status,'event_date'=>$event,'dispatch_date'=>$dispatch,'reason'=>$reason,'warehouse_ack'=>$cancel?1:0],'snapshot'=>$snapshot,'source'=>$b,'effects'=>$effects,'action'=>$cancel?'Cancel / release':$row['action'],'before_status'=>$o['platform_status'],'plan_digest'=>$plan['digest'],'user_id'=>current_user()['id']];$saved['digest']=hash('sha256',json_encode($saved));return $saved;
}
function oi_manual_apply($saved){om_require();if((int)$saved['user_id']!==current_user()['id']||strtotime($saved['snapshot'])<time()-900)throw new Exception('Preview expired. Review the order again.');return process_transaction(function()use($saved){om_order($saved['order_id'],true);unset($GLOBALS['OM_RESERVED'],$GLOBALS['OA_REPORTS']);$fresh=oi_manual_plan($saved['order_id'],$saved['input'],$saved['snapshot']);if(!hash_equals($saved['digest'],$fresh['digest']))throw new Exception('Order or stock changed. Review again before confirming.');$b=$fresh['source'];$id=om_stage_rows('Status',$b['meta'],$b['rows'],'Manual status update');$p=om_plan(om_upload($id));om_confirm($id,$p['digest'],true);$after=om_order($saved['order_id']);$mov=om_query('SELECT p.outflow_id,f.txn_date,f.product_id,f.qty FROM om_postings p JOIN outflows f ON f.id=p.outflow_id WHERE p.order_id=?',[$after['id']])->fetchAll();om_event($after['id'],$id,'Manual status updated',['source'=>'Manual','before_status'=>$fresh['before_status'],'after_status'=>$after['platform_status'],'reported_status'=>$fresh['input']['status'],'actual_event_date'=>$fresh['input']['event_date'],'reason'=>$fresh['input']['reason'],'action'=>$fresh['action'],'effects'=>$fresh['effects'],'movements'=>$mov]);audit('Manual order status update','Order Monitoring',$after['order_no'],$fresh['before_status'].' -> '.$after['platform_status'].'; reported '.$fresh['input']['status'].'; '.$fresh['input']['reason']);return ['order'=>$after,'action'=>$fresh['action'],'upload_id'=>$id];});}
function oi_product_label($id){$products=gm_products();$p=$products[(int)$id]??null;return $p?($p['name'].' · '.$p['master_sku']):'Product #'.(int)$id;}
function oi_event_details($event,$d,$includeSummary=false){
 if($event==='Order references updated'&&!empty($d['after_refs'])){ $before=$d['before_refs']??[];$after=$d['after_refs'];om_table(['Reference','Before','After'],[['Booking SN',$before['booking_sn']??'',$after['booking_sn']??''],['Assigned Order ID',$before['assigned_order_id']??'',$after['assigned_order_id']??''],['Tracking Numbers',implode(' / ',$before['tracking_numbers']??[]),implode(' / ',$after['tracking_numbers']??[])]]);echo '<p>No physical stock or reservation change.</p>';return;}
 $shown=false;$info=[];if(($d['snapshot_precision']??'')==='date'&&!empty($d['snapshot']))$d['snapshot']=substr($d['snapshot'],0,10);
 foreach(['original_export_time','previous_export_time','corrected_export_time'] as $exportKey)if(!empty($d[$exportKey]))$d[$exportKey]=substr($d[$exportKey],0,10);if($includeSummary)foreach(['before_status'=>'Previous status','after_status'=>'Updated status','reported_status'=>'Reported status','actual_event_date'=>'Actual event date','reason'=>'Reason','source'=>'Source'] as $key=>$label)if(isset($d[$key])&&is_scalar($d[$key])&&(string)$d[$key]!=='')$info[$label]=(string)$d[$key];
 foreach(['actual_event_date'=>'Actual event date','recorded_fulfillment_date'=>'Recorded fulfillment date','system_encoding_time'=>'System encoding time','original_export_time'=>'Original file export date','previous_export_time'=>'Previous export date','corrected_export_time'=>'Corrected export date','previous_mapping'=>'Previous mapping','original_correction_at'=>'Original correction recorded at','snapshot'=>(($d['snapshot_precision']??'')==='date'?'Verified export date':'Verified / export time'),'posting'=>'Inventory posting','last_status'=>'Previous recorded status','status'=>'Reported status','before'=>'Previous value','after'=>'Corrected value','date'=>'Corrected date','next'=>'Next follow-up date','resolution'=>'Resolution','outflow_id'=>'Outflow reference','reference'=>'Reference','request_id'=>'Correction request','row'=>'Source row','released_units'=>'Released reservation (pcs)','return_batch_id'=>'Return receipt reference','received_total'=>'Physically received (pcs)'] as $key=>$label)if(isset($d[$key])&&is_scalar($d[$key])&&(string)$d[$key]!=='')$info[$label]=(string)$d[$key];
 if(array_key_exists('stock_changed',$d))$info['Stock effect']=$d['stock_changed']?'See linked inventory movement':'No physical stock change';
 if(isset($d['physical_delta']))$info['Physical stock change']=((int)$d['physical_delta']>0?'+':'').(int)$d['physical_delta'].' pcs';
 if(!empty($d['reservation_released']))$info['Reservation']='Released; physical stock unchanged';
 if($info){echo '<dl class="oi-detail-list">';foreach($info as $label=>$value)echo '<dt>'.e($label).'</dt><dd>'.e($value).'</dd>';echo '</dl>';$shown=true;}
 if(!empty($d['errors'])){echo '<p><b>Needs checking</b></p><ul>';foreach($d['errors'] as $error)if(is_scalar($error))echo '<li>'.e($error).'</li>';echo '</ul>';$shown=true;}
 if(!empty($d['totals'])&&is_array($d['totals'])){$rows=[];foreach($d['totals'] as $pid=>$qty)if(is_scalar($qty))$rows[]=[oi_product_label($pid),(int)$qty.' pcs'];if($rows){echo '<h4>Products</h4>';om_table(['Product / SKU','Quantity'],$rows);$shown=true;}}
 $lines=$d['source_lines']??$d['lines']??[];if(is_array($lines)&&$lines){$rows=[];foreach($lines as $line){if(!is_array($line))continue;$components=$line['components']??[];if($components){foreach($components as $c)$rows[]=[oi_product_label($c['product_id']),(int)($line['qty']??0)*(int)$c['per_bundle'].' pcs'];}else $rows[]=[trim(($line['name']??$line['item']??'Product').' '.($line['variation']??'')),(int)($line['qty']??0).' pcs'];}if($rows){echo '<h4>Order Items</h4>';om_table(['Product / SKU','Quantity'],$rows);$shown=true;}}
 if(!empty($d['components'])){echo '<h4>Product Mapping</h4>';om_table(['Product / SKU','Units per item'],array_map(fn($c)=>[oi_product_label($c['product_id']),(int)$c['per_bundle']],$d['components']));$shown=true;}
 if(!empty($d['effects'])){$rows=[];foreach($d['effects'] as $r)$rows[]=[$r['product'].' · '.$r['sku'],$r['physical_before'].' → '.$r['physical_after'],$r['reserved_before'].' → '.$r['reserved_after'],$r['available_before'].' → '.$r['available_after']];echo '<h4>Stock Effect</h4>';om_table(['Product / SKU','Physical','Reserved','Available'],$rows);$shown=true;}
 if(!empty($d['movements'])){echo '<h4>Linked Movements</h4>';om_table(['Reference','Date','Product / SKU','Quantity'],array_map(fn($r)=>['Outflow #'.$r['outflow_id'],$r['txn_date'],oi_product_label($r['product_id']),(int)$r['qty'].' pcs'],$d['movements']));$shown=true;}
 elseif(!empty($d['outflow_ids'])){echo '<p><b>Linked movements:</b> '.e(implode(', ',array_map(fn($v)=>'Outflow #'.(int)$v,$d['outflow_ids']))).'</p>';$shown=true;}
 if(!$shown)echo '<p class="muted">No additional details were recorded for this event.</p>';
}
function oi_history($id){$o=om_order($id);echo '<h2>Update History</h2><p>'.e($o['platform'].' · '.$o['order_no']).'</p><p>Confirmed: <b>'.e($o['platform_status']).'</b> · Reported: '.e(oa_reported($o)['status']).' · '.e($o['posting']).'</p>';foreach(om_query('SELECT e.*,u.name actor,b.filename FROM om_events e LEFT JOIN users u ON u.id=e.user_id LEFT JOIN om_uploads b ON b.id=e.upload_id WHERE e.order_id=? ORDER BY e.id DESC',[$id]) as $ev){$d=json_decode($ev['details_json'],true)?:[];echo '<article class="oi-event"><b>'.e($ev['event_type']).'</b><p>'.e($ev['created_at'].' · '.($ev['actor']?:'System')).'</p>';if(isset($d['before_status']))echo '<p>'.e($d['before_status'].' → '.($d['after_status']??$d['reported_status']??'')).'</p>';if(!empty($d['actual_event_date']))echo '<p>Actual event: '.e($d['actual_event_date']).'</p>';if(!empty($d['reason']))echo '<p>Reason: '.e($d['reason']).'</p>';echo '<p class="muted">Source: '.e($d['source']??($ev['upload_id']?($ev['filename']?:'Upload #'.$ev['upload_id']):'System / Inflow')).'</p>';if(!empty($d['effects']))foreach($d['effects'] as $s)echo '<p>'.e($s['sku'].' · Physical '.$s['physical_before'].' → '.$s['physical_after'].' · Reserved '.$s['reserved_before'].' → '.$s['reserved_after']).'</p>';echo '<details class="oi-readable-details"><summary>View Details</summary>';oi_event_details($ev['event_type'],$d);echo '</details></article>';}echo '<p class="muted">History is permanent. Actual event dates and recorded times are separate.</p>';}
function oi_manual_form($id){om_require();$o=om_order($id);echo '<h2>Update Order Status</h2><p>'.e($o['platform'].' · '.$o['order_no']).'</p><p>Current status: <b>'.e($o['platform_status']).'</b> · '.e($o['posting']).'<br>Actual fulfillment: '.e($o['fulfillment_date']).' · Encoded: '.e($o['created_at']).'</p>';if(sp_terminal_delivery($o))echo '<p class="alert info">Delivered / Completed status is locked. You may report Return / Refund only. Returned quantity is received separately in Inflow.</p>';oi_form('manual_preview',['order_id'=>$id]);echo '<div class="oi-fields">';om_select('status','New status',sp_manual_statuses($o),sp_terminal_delivery($o)?'Return / Refund':(oc_pending_cancellation($o)?'Cancelled':$o['platform_status']));echo '<label>Actual event date<input type="date" name="event_date" max="'.date('Y-m-d').'" value="'.date('Y-m-d').'" required></label>';if($o['posting']==='Not Posted')echo '<label data-oi-dispatch hidden>Actual dispatch date (for Delivered / Completed)<input type="date" name="dispatch_date" max="'.date('Y-m-d').'" value="'.e($o['fulfillment_date']).'"></label>';echo '<label>Reason / verified reference<textarea name="reason" minlength="3" maxlength="2000" required></textarea></label></div>';if($o['posting']==='Not Posted')echo '<label class="oi-ack" data-oi-warehouse hidden><input type="checkbox" name="warehouse_ack" value="1"> All units remain in the warehouse; no dispatch was posted.</label>';echo '<p class="muted">Returns after dispatch require actual receiving in Inflow. Correct wrong fulfillment dates separately.</p><button class="btn primary">Review Stock Effect</button></form>';}
function oi_manual_preview_html($p,$token){$o=om_order($p['order_id']);echo '<h2>Confirm Status Update</h2><p><b>'.e($o['order_no']).'</b> · '.e($p['before_status'].' → '.$p['input']['status']).'</p><p>Actual event: '.e($p['input']['event_date']).'<br>Reason: '.e($p['input']['reason']).'</p><p><b>'.e($p['action']).'</b></p>';om_table(['Product','Physical','Reserved','Available'],array_map(fn($r)=>[$r['sku'].' / '.$r['product'],$r['physical_before'].' → '.$r['physical_after'],$r['reserved_before'].' → '.$r['reserved_after'],$r['available_before'].' → '.$r['available_after']],$p['effects']));if($p['action']==='Report for Inflow confirmation')echo '<p class="alert warn">The reported status is recorded. Confirmed status / physical receipt remains subject to Inflow confirmation. No stock will be added.</p>';echo '<p>Do you want to continue updating the status of this order?</p>';oi_form('manual_apply',['token'=>$token,'order_id'=>$o['id']]);echo '<label class="oi-ack"><input type="checkbox" name="confirm_ack" value="1" required> I reviewed the status, actual date and stock effect.</label><div class="om-actions"><button type="button" class="btn ghost" data-oi="manual" data-order="'.$o['id'].'">Back</button><button class="btn primary">Yes, Update Status</button></div></form>';}
function oi_upload_panel($b){if($b['status']!=='Review'||!om_allowed()||(access_profile()!=='Admin'&&(int)$b['created_by']!==current_user()['id']))return;echo '<details class="oi-upload"><summary>Remove / Restore Orders from This Upload</summary><p>Entire orders, including all items, are excluded only from this upload. Existing orders and stocks are retained.</p>';oi_form('exclude',['upload_id'=>$b['id'],'revision'=>$b['revision']]);echo '<input type="hidden" name="selection_json" value="[]"><label>Reason<input name="reason" minlength="3" required></label><label>Action<select name="undo"><option value="0">Remove from Upload</option><option value="1">Undo Removal / Restore</option></select></label><label class="oi-ack"><input type="checkbox" data-oi-select-all> Select all orders in this upload (all pages)</label><div class="oi-selection">';foreach(array_values(array_unique(array_map('strval',array_column($b['rows'],'order')))) as $no){$ex=oi_exclusion($b,$no);echo '<label class="oi-ack"><input type="checkbox" data-oi-order value="'.e($no).'"> '.e($no).($ex?' · REMOVED · '.e($ex['reason']):'').'</label>';}echo '</div><button class="btn secondary">Review Selected Orders</button></form></details>';}
